&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Standort: Frankfurt (Hybrid) |&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Practice Area&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;: Banking &amp;amp; Payments | Art:&amp;nbsp;Festanstellung&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Begleite führende Finanzinstitute bei der Transformation moderner Zahlungsverkehrslandschaften.&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Die Rolle&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Capco sucht engagierte (Senior) Consultants mit Leidenschaft für Payments Transformation und digitale Innovationen im Zahlungsverkehr. In dieser Rolle unterstützt Du unsere Kunden bei anspruchsvollen Transformationsprojekten entlang der gesamten Wertschöpfungskette moderner Payment-Lösungen – von der Business Analyse und Fachkonzeption über&amp;nbsp;Testing&amp;nbsp;bis hin zur Implementierungsbegleitung.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du arbeitest an der Schnittstelle zwischen Fachbereich und Technologie und erhältst Einblicke in moderne Payment-Architekturen, regulatorische Anforderungen und innovative Zahlungsverkehrslösungen innerhalb eines dynamischen und internationalen Umfelds.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Deine&amp;nbsp;Aufgaben&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Begleitung anspruchsvoller Beratungsprojekte im Zahlungsverkehrsumfeld – von der Business Analyse und Fachkonzeption bis hin zu&amp;nbsp;Testing&amp;nbsp;und Implementierungsbegleitung&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Mitarbeit an Transformationsprojekten rund um moderne Zahlungsverkehrsarchitekturen, regulatorische Anforderungen und innovative Payment-Lösungen&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Zusammenarbeit mit Kunden und Projektteams sowohl in klassischen Wasserfallprojekten als auch in agilen&amp;nbsp;Delivery-Umfeldern&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Übernahme von Verantwortung für eigene Themenbereiche bis hin zur Steuerung von Teilprojekten und kleineren Projektteams&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Aktive Mitgestaltung interner Themen sowie Unterstützung bei der fachlichen, methodischen und persönlichen Weiterentwicklung innerhalb von Capco&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Dein&amp;nbsp;Profil&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Erfolgreich&amp;nbsp;abgeschlossenes&amp;nbsp;Hochschulstudium&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Relevante praktische Erfahrung in Beratungsprojekten im Finanzdienstleistungsumfeld&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Großes&amp;nbsp;Interesse&amp;nbsp;an&amp;nbsp;Payments&amp;nbsp;sowie&amp;nbsp;Kenntnisse&amp;nbsp;relevanter&amp;nbsp;Themen&amp;nbsp;und&amp;nbsp;Prozesse&amp;nbsp;wie&amp;nbsp;PSD3/PSR,&amp;nbsp;SEPA-Classic,&amp;nbsp;Instant Payments, TARGET2, TIPS, Clearing &amp;amp; Settlement, Cash&amp;nbsp;Management&amp;nbsp;oder&amp;nbsp;Correspondent&amp;nbsp;Banking&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ausgeprägte analytische und konzeptionelle Fähigkeiten sowie eine teamorientierte und kundenfokussierte Arbeitsweise&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Fließende Deutsch- und Englischkenntnisse sowie uneingeschränkte Mobilität im nationalen und internationalen Projektumfeld&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nice to have&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Erfahrung in Business Analyse, Fachkonzeption,&amp;nbsp;Testing&amp;nbsp;oder Cut-Over-Aktivitäten innerhalb von Transformationsprojekten&amp;nbsp;im Zahlungsverkehr&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Kenntnisse regulatorischer Anforderungen im Zahlungsverkehrsumfeld, beispielsweise PSD3 oder PSR&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Erfahrung mit agilen Methoden oder hybriden Projektansätzen&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Verständnis moderner Payment-Architekturen, APIs oder digitaler Zahlungsmodelle&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Erste Erfahrungen in der Steuerung kleinerer Arbeitspakete oder Teilprojekte&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
